/* From Uiverse.io by gharsh11032000 - Tags: gradient, card, hover, hover effect */
.__UIV_SCOPE__ .card {
  width: 300px;
  height: 200px;
  background-color: #FF3CAC;
  background-image: linear-gradient(225deg, #FF3CAC 0%, #784BA0 50%, #2B86C5 100%);
  color: white;
  border-radius: 8px;
  overflow: hidden;
  position: relative;
  perspective: 1000px;
  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);
  cursor: pointer;
}

.__UIV_SCOPE__ .card-content {
  padding: 20px;
  position: relative;
  z-index: 1;
}

.__UIV_SCOPE__ .card:hover {
  transform: scale(1.05);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
}

.__UIV_SCOPE__ .card:before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 60%;
  background-color: rgba(0, 0, 0, 0.1);
  opacity: 0;
  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);
  z-index: 1;
}

.__UIV_SCOPE__ .card:hover:before {
  opacity: 1;
}

.__UIV_SCOPE__ .card .card-title {
  font-size: 24px;
  font-weight: 700;
  margin-bottom: 8px;
  text-transform: capitalize;
}

.__UIV_SCOPE__ .card .card-para {
  font-size: 16px;
  opacity: 0.8;
}

.__UIV_SCOPE__ .card-content {
  transform: translateY(50%);
  transition: all 0.5s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .card:hover .card-content {
  transform: translateY(0%);
}
